-- Large batch cross-referenced against the existing 218-exercise library
-- (dedup against real DB names, not just eyeballing) and against
-- near-duplicates within the submitted list itself (e.g. many stretch,
-- throw, and cone-drill variants that are functionally the same movement
-- under a different name were consolidated to one entry). Written
-- originally, same tagging vocabulary and category set as every prior
-- batch — no new contraindication tags or categories introduced.
-- Equipment: TRX/suspension exercises use the existing "suspension" type
-- (already covers TRX — see equipmentLabel() in rules.ts for the display
-- name). No new equipment types were needed for this batch.

insert into exercises
  (name, description, pattern, category, muscle_groups, equipment_types, difficulty, cues, contraindication_tags, unilateral)
